con:testCase.con:setupScript:
import groovy.xml.XmlSlurper

// === НАСТРОЙКИ ===
def xsdUrl = "https://ws.dpd.ru/services/geography2?xsd=1"
def methodName = "getCitiesCashPay"
def xsdFile = new File("C:/soapui/xsd/geography2.xsd")

log.info "Проверка XSD для метода: ${methodName}"

// === СКАЧИВАЕМ ТЕКУЩУЮ XSD ===
def currentXsdText = new URL(xsdUrl).getText("UTF-8")

// === ЕСЛИ ЭТО ПЕРВЫЙ ЗАПУСК ===
if (!xsdFile.exists()) {
    xsdFile.parentFile.mkdirs()
    xsdFile.text = currentXsdText
    log.warn "Эталонная XSD не найдена. Сохранил текущую версию."
    return
}

// === ЧИТАЕМ СТАРУЮ XSD ===
def oldXsdText = xsdFile.text

// === ПАРСИНГ ===
def currentXsd = new XmlSlurper(false, false).parseText(currentXsdText)
def oldXsd     = new XmlSlurper(false, false).parseText(oldXsdText)

// namespace XSD
def xs = new groovy.xml.Namespace("http://www.w3.org/2001/XMLSchema", "xs")

// === ФУНКЦИЯ ДОСТАЁТ ELEMENTS МЕТОДА ===
def extractElements = { xsd ->
    def elements = [] as Set

    xsd.depthFirst().findAll {
        it.name() == xs.element &&
        it.@name.text() == methodName
    }.each { method ->
        method.depthFirst().findAll {
            it.name() == xs.element && it.@name.text()
        }.each {
            elements << it.@name.text()
        }
    }

    return elements
}

def oldElements = extractElements(oldXsd)
def newElements = extractElements(currentXsd)

// === СРАВНЕНИЕ ===
def addedElements = newElements - oldElements

if (!addedElements.isEmpty()) {
    log.error "❌ ОБНАРУЖЕНЫ НОВЫЕ ПАРАМЕТРЫ В XSD!"
    addedElements.each {
        log.error "  ➕ ${it}"
    }
    assert false : "XSD изменилась: добавлены новые параметры (${addedElements.join(', ')})"
}

// === ЕСЛИ ВСЁ ОК — ОБНОВЛЯЕМ ЭТАЛОН ===
xsdFile.text = currentXsdText
log.info "✅ XSD без изменений для ${methodName}"
